def select(pool, n_rsrv, max_bs, n_slots):
    batch = []
    for req in sorted(pool, key=lambda r: r.arrival):  # FCFS
        if req.state == "RUNNING":
            continue
        if len(batch) == max_bs:
            break
        if req.state == "INITIATION":           # first time scheduled
            if n_rsrv + req.max_tokens > n_slots:
                break                           # cannot guarantee it
            n_rsrv += req.max_tokens            # reserve worst case
        batch.append(req)
    return batch, n_rsrv
